UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Aníbal Bravo, nombre artístico de Ramón de los","type":"text"},{"type":"hardBreak"},{"text":" Santos, nació el 24 de abril de 1956 en Las Matas de Farfán, San Juan ","type":"text"},{"type":"hardBreak"},{"text":"de la Maguana, República Dominicana. Desde temprana edad mostró ","type":"text"},{"type":"hardBreak"},{"text":"inclinaciones musicales, influenciado por su entorno familiar: su madre,","type":"text"},{"type":"hardBreak"},{"text":" María Regla Aquino, cantaba y su padre, Manuel de los Santos, tocaba la","type":"text"},{"type":"hardBreak"},{"text":" guitarra.","type":"text"}]},{"type":"paragraph","content":[{"text":"Aníbal Bravo y su orquesta fueron de los mejores merengueros en la ","type":"text"},{"type":"hardBreak"},{"text":"época de los años 70’s, 80’s y 90’s, tiempo de buena música, usando ","type":"text"},{"type":"hardBreak"},{"text":"bailes propios, con voz auténtica e inigualable en estos tiempos. Con 41","type":"text"},{"type":"hardBreak"},{"text":" temas, de los cuales la mayoría fueron éxitos a nivel nacional e ","type":"text"},{"type":"hardBreak"},{"text":"internacional.","type":"text"}]},{"type":"paragraph","content":[{"text":"A los 15 años, Aníbal ingresó a la banda de música municipal de su ","type":"text"},{"type":"hardBreak"},{"text":"pueblo como batutero y comenzó estudios formales de música con los ","type":"text"},{"type":"hardBreak"},{"text":"maestros Almánzar y Luis Pérez.","type":"text"}]},{"type":"paragraph","content":[{"text":"Aquellos tiempos de los 80’s no tienen comparación; fue un gran auge ","type":"text"},{"type":"hardBreak"},{"text":"artístico para los dominicanos y aquellos que no lo eran, ya que gozaban","type":"text"},{"type":"hardBreak"},{"text":" de esos merengues de corazón y que alegraban aquellos con su melodía y ","type":"text"},{"type":"hardBreak"},{"text":"buenas letras.","type":"text"}]},{"type":"paragraph","content":[{"text":"Entre sus éxitos más sonados están: “La Revancha”, “El Gatico”, “El ","type":"text"},{"type":"hardBreak"},{"text":"Muñequito”, “Filete”, “Llorona”, “Chica de Hoy”, “Mi Cocha Pechocha”, ","type":"text"},{"type":"hardBreak"},{"text":"“La Taberna”, “El Preso” y “Zape pa’lla”.","type":"text"}]},{"type":"paragraph","content":[{"text":"Ramón de los Santos, mejor conocido artísticamente como Aníbal Bravo,","type":"text"},{"type":"hardBreak"},{"text":" nació el 24 de abril de 1956 en Las Matas de Farfán, San Juan de la ","type":"text"},{"type":"hardBreak"},{"text":"Maguana. A los 15 años ingresó a la banda de música municipal de su ","type":"text"},{"type":"hardBreak"},{"text":"pueblo, en la que se desempeñaba como batutero. Luego formó un pequeño ","type":"text"},{"type":"hardBreak"},{"text":"grupo musical junto a sus hermanos Teónilo, Emilio, Fernando y Miguel. ","type":"text"},{"type":"hardBreak"},{"text":"Cuando tenía 17 años, sufrió un accidente jugando béisbol al deslizarse ","type":"text"},{"type":"hardBreak"},{"text":"en la segunda base.","type":"text"}]},{"type":"paragraph","content":[{"text":"Sus cantantes fueron Blas Durán, Bobby Rafael, Sigfrido Rey, Peter ","type":"text"},{"type":"hardBreak"},{"text":"Cruz, Marcos Burdier, Félix Cumbé, Jochy Hernández, Leo Palacio, “El ","type":"text"},{"type":"hardBreak"},{"text":"Chepe”, Ileana Reynoso, Heydy Bello, Johnny Vargas, Tony Bravo, Oscar ","type":"text"},{"type":"hardBreak"},{"text":"Pérez, Eliécer y Birmania.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'anibal-bravo' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Aníbal Bravo, nombre artístico de Ramón de los Santos, nació el 24 de abril de 1956 en Las Matas de Farfán, San Juan de la Maguana, República Dominicana. Desde temprana edad mostró inclinaciones musicales, influenciado por su entorno familiar: su madre, María Regla Aquino, cantaba y su padre, Manuel de los Santos, tocaba la guitarra.

Aníbal Bravo y su orquesta fueron de los mejores merengueros en la época de los años 70’s, 80’s y 90’s, tiempo de buena música, usando bailes propios, con voz auténtica e inigualable en estos tiempos. Con 41 temas, de los cuales la mayoría fueron éxitos a nivel nacional e internacional.

A los 15 años, Aníbal ingresó a la banda de música municipal de su pueblo como batutero y comenzó estudios formales de música con los maestros Almánzar y Luis Pérez.

Aquellos tiempos de los 80’s no tienen comparación; fue un gran auge artístico para los dominicanos y aquellos que no lo eran, ya que gozaban de esos merengues de corazón y que alegraban aquellos con su melodía y buenas letras.

Entre sus éxitos más sonados están: “La Revancha”, “El Gatico”, “El Muñequito”, “Filete”, “Llorona”, “Chica de Hoy”, “Mi Cocha Pechocha”, “La Taberna”, “El Preso” y “Zape pa’lla”.

Ramón de los Santos, mejor conocido artísticamente como Aníbal Bravo, nació el 24 de abril de 1956 en Las Matas de Farfán, San Juan de la Maguana. A los 15 años ingresó a la banda de música municipal de su pueblo, en la que se desempeñaba como batutero. Luego formó un pequeño grupo musical junto a sus hermanos Teónilo, Emilio, Fernando y Miguel. Cuando tenía 17 años, sufrió un accidente jugando béisbol al deslizarse en la segunda base.

Sus cantantes fueron Blas Durán, Bobby Rafael, Sigfrido Rey, Peter Cruz, Marcos Burdier, Félix Cumbé, Jochy Hernández, Leo Palacio, “El Chepe”, Ileana Reynoso, Heydy Bello, Johnny Vargas, Tony Bravo, Oscar Pérez, Eliécer y Birmania.' WHERE slug = 'anibal-bravo';
