UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"José Abreu Vargas \"Cheché\", \"La Negra Pola\", Nació el 26 de julio del año 1939 en Manoguayabo, Santo Domingo, capital de la República Dominicana. Legendario Cantante, Compositor Guitarrista y Director de orquesta, de los más trascendentales de Quisqueya. En el año 1961 comienza a incursionar en el arte de la música, formando \"El Sexteto Manoguayabo\", este nombre se debió que todo sus integrantes eran oriundos de esta comunidad, entre ellos estaban Pedro Germán Benítez (Guitarra Segunda), Cheché Abreu (Tresista y director del grupo), Pablo Abreu (Bajista), Gregorio Germán (Bongosero), Eligio del Pozo (Maraca y Guira) y Pablo Santos Rodríguez -Chichón- (Trompeta). El grupo debutó profesionalmente el 25 de diciembre en 1963 en la \"Gran Parada Bar\" lugar de esparcimiento localizado en Manoguayabo, para ese entonces. El Sexteto de Manoguayabo seguía firme y adquiriendo popularidad, luego aumentó su número de seis miembros a trece, convirtiéndose en a la agrupación \"Cheché Abreu y sus Colosos\", esto ocurre en octubre del año 1966. En el año de 1970 comienzan su proceso de grabación, comenzaron a grabar en el Salón Mozart, a cambio de promoción; luego en la Dixie Records, en Miami, en el cual grabaron 5 LP; también a cambio de promoción; luego grabaron 4 LP a Mateo San Martin de la Cubaney, a cambio también de promoción. Ninguna de estas Empresas promocionaron el grupo en la República Dominicana hasta que en el año 1978 comienzan a grabar para \"La Guarachita\" la cual, aunque a cambio de promoción también, dio a conocer la orquesta a nivel mundial, viajando la agrupación, llevando el merengue y El Mangué, ritmo creado por Cheché Abreu, en toda América y Europa. Por nuestra música, el grupo de Cheche Abreu y sus colosos fue el primer grupo de República Dominicana de llenar el Madison Square Garden (USA). El grupo se presento en todos los Estados Unidos con el tema \"La Negra Pola\", también tuvo éxitos con el tema en Venezuela, España, Puerto Rico, Haití, Aruba, Curazao, Donaire, San Martin y muchos países más de Centro y Sur América. Luego de cumplido el contrato con “La Guarachita”, la agrupación entra a grabar con la casa Combo Records, de Raffi Car.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'cheche-abreu' AND d.locale = 'es' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_es = 'José Abreu Vargas "Cheché", "La Negra Pola", Nació el 26 de julio del año 1939 en Manoguayabo, Santo Domingo, capital de la República Dominicana. Legendario Cantante, Compositor Guitarrista y Director de orquesta, de los más trascendentales de Quisqueya. En el año 1961 comienza a incursionar en el arte de la música, formando "El Sexteto Manoguayabo", este nombre se debió que todo sus integrantes eran oriundos de esta comunidad, entre ellos estaban Pedro Germán Benítez (Guitarra Segunda), Cheché Abreu (Tresista y director del grupo), Pablo Abreu (Bajista), Gregorio Germán (Bongosero), Eligio del Pozo (Maraca y Guira) y Pablo Santos Rodríguez -Chichón- (Trompeta). El grupo debutó profesionalmente el 25 de diciembre en 1963 en la "Gran Parada Bar" lugar de esparcimiento localizado en Manoguayabo, para ese entonces. El Sexteto de Manoguayabo seguía firme y adquiriendo popularidad, luego aumentó su número de seis miembros a trece, convirtiéndose en a la agrupación "Cheché Abreu y sus Colosos", esto ocurre en octubre del año 1966. En el año de 1970 comienzan su proceso de grabación, comenzaron a grabar en el Salón Mozart, a cambio de promoción; luego en la Dixie Records, en Miami, en el cual grabaron 5 LP; también a cambio de promoción; luego grabaron 4 LP a Mateo San Martin de la Cubaney, a cambio también de promoción. Ninguna de estas Empresas promocionaron el grupo en la República Dominicana hasta que en el año 1978 comienzan a grabar para "La Guarachita" la cual, aunque a cambio de promoción también, dio a conocer la orquesta a nivel mundial, viajando la agrupación, llevando el merengue y El Mangué, ritmo creado por Cheché Abreu, en toda América y Europa. Por nuestra música, el grupo de Cheche Abreu y sus colosos fue el primer grupo de República Dominicana de llenar el Madison Square Garden (USA). El grupo se presento en todos los Estados Unidos con el tema "La Negra Pola", también tuvo éxitos con el tema en Venezuela, España, Puerto Rico, Haití, Aruba, Curazao, Donaire, San Martin y muchos países más de Centro y Sur América. Luego de cumplido el contrato con “La Guarachita”, la agrupación entra a grabar con la casa Combo Records, de Raffi Car.' WHERE slug = 'cheche-abreu';
DELETE FROM editorial_entity_references WHERE editorial_document_id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'cheche-abreu' AND d.locale = 'es' AND d.document_type = 'artist_biography');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Cherito was one of the most recognizable voices in Dominican merengue at the end of the twentieth century: a singer, songwriter, arranger and producer, and the figure who turned The New York Band into one of the most influential groups of merengue''s golden age. His real name was José Bienvenido Jiménez Sosa; \"Cherito\" began as a diminutive of his father''s name, Chery.","type":"text"}]},{"type":"paragraph","content":[{"text":"Origins and Family","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He was born on August 23, 1968, in Santo Domingo, the son of Chery Jiménez, a well-known Dominican artistic entrepreneur and promoter, and Georgina Sosa. He grew up immersed in the musical world his father had built as a driving force behind merengue groups based out of New York, an environment that shaped his artistic calling from childhood.","type":"text"}]},{"type":"paragraph","content":[{"text":"Early Talent","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"From a young age he showed a strong pull toward music, teaching himself guitar and piano. By 18 he was already writing his own songs — among them \"Nadie como tú\" — which he performed for his father, who would later fold them into his group''s repertoire.","type":"text"}]},{"type":"paragraph","content":[{"text":"The Birth of The New York Band","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In November 1988, at just 19 years old, Cherito joined The New York Band, the orchestra his father had founded in New York in 1986. He became the group''s lead voice, songwriter, arranger and co-producer, and the band stood out for modernizing merengue by fusing it with pop, house and R&B sounds, along with a cosmopolitan stage image that helped carry the genre beyond the Dominican Republic.","type":"text"}]},{"type":"paragraph","content":[{"text":"Hits and Rise to Prominence","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Under his vocal leadership, The New York Band recorded some of the most remembered merengue songs of the era: \"Si tú no estás\" (recorded for Christmas 1987 and one of the group''s biggest hits), \"Nadie como tú,\" \"Dame vida,\" \"Si tú eres mi hombre,\" \"Dancing Mood,\" \"Amada mía\" and \"Colé.\" With Cherito at the front, the group sold more than 2.5 million records across markets including Puerto Rico, the United States, Mexico, Colombia, Venezuela, Spain and the Dominican Republic, and performed on stages such as Madison Square Garden.","type":"text"}]},{"type":"paragraph","content":[{"text":"Departure and Life as a Soloist and Producer","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1995, Cherito stepped away from the group to launch a solo and production career under the artistic name \"Chery X,\" releasing the albums Cherito (1992), Que Tentación (Sony, 1995) — which produced the single \"Qué tentación\" — the compilation The Best of Cherito XXX: Love & Kisses (1996) and Tu Amor (BMG, 1997). The New York Band carried on without him until it formally disbanded in 1998.","type":"text"}]},{"type":"paragraph","content":[{"text":"In the years that followed, he focused mainly on songwriting, production and arranging, working with artists such as Celia Cruz, Wilfrido Vargas and Olga Tañón, collaborating with producer Sergio George, and serving as an exclusive composer for Warner Music Group.","type":"text"}]},{"type":"paragraph","content":[{"text":"Comeback and the 2016 Reunion","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2007 he returned to the stage as a soloist with a merengue project with a more urban sound, which produced his biggest hit of that era, \"Ella quiere un pedazo,\" along with singles such as \"Vivir mi vida,\" \"El protagonista,\" \"Sé que te perdí\" (with Pavel Núñez) and \"Déjalo pa''l lunes.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"In 2015 he took part in a tribute performance for The New York Band at the Soberano Awards, and in 2016, after receiving the Merit award, the original lineup formally reunited and launched the \"Re:Encuentro World Tour,\" which was met with great enthusiasm from audiences. Reflecting on that moment, Cherito said: \"He wasn''t wrong, and we''re reaping what we sowed,\" referring to his father''s vision in founding the band.","type":"text"}]},{"type":"paragraph","content":[{"text":"Passing","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cherito died suddenly on July 24, 2019, at age 50, after suffering a heart attack in his sleep at his home in Santo Domingo. He was survived by his wife, Aleyda, and his children Gabriel and Lía, as well as a son from a previous relationship.","type":"text"}]},{"type":"paragraph","content":[{"text":"Discography","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"As \"Chery X\" (solo period, 1990s): Cherito (1992), Que Tentación (Sony, 1995), The Best of Cherito XXX: Love & Kisses (compilation, 1996) and Tu Amor (BMG, 1997).","type":"text"}]},{"type":"paragraph","content":[{"text":"As \"Cherito\" (solo comeback, 2010s): \"Ella quiere un pedazo\" (2013, re-released 2015), \"Vivir mi vida\" (2013), \"El protagonista\" (2013), \"Si tú eres mi hombre\" (with Divas by Jiménez, 2014), \"Sé que te perdí\" (with Pavel Núñez, 2014) and \"Déjalo pa''l lunes\" (2016).","type":"text"}]},{"type":"paragraph","content":[{"text":"With The New York Band (selected hits, 1988–1995): \"Si tú no estás,\" \"Nadie como tú,\" \"Dame vida,\" \"Si tú eres mi hombre,\" \"Dancing Mood,\" \"Amada mía\" and \"Colé.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Collaborations","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"As a producer, arranger and composer he worked with Celia Cruz, Wilfrido Vargas, Olga Tañón and producer Sergio George, and collaborated on singles with Pavel Núñez and Divas by Jiménez.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Cherito is remembered as the lead voice of The New York Band, one of the most influential merengue groups of the 1980s and 90s, and as the songwriter behind tracks that became generational classics of the genre. His work helped carry Dominican merengue to international stages and markets, and he continues to be remembered as one of the defining voices of merengue''s golden age.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'cherito' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Cherito was one of the most recognizable voices in Dominican merengue at the end of the twentieth century: a singer, songwriter, arranger and producer, and the figure who turned The New York Band into one of the most influential groups of merengue''s golden age. His real name was José Bienvenido Jiménez Sosa; "Cherito" began as a diminutive of his father''s name, Chery.

**Origins and Family**

He was born on August 23, 1968, in Santo Domingo, the son of Chery Jiménez, a well-known Dominican artistic entrepreneur and promoter, and Georgina Sosa. He grew up immersed in the musical world his father had built as a driving force behind merengue groups based out of New York, an environment that shaped his artistic calling from childhood.

**Early Talent**

From a young age he showed a strong pull toward music, teaching himself guitar and piano. By 18 he was already writing his own songs — among them "Nadie como tú" — which he performed for his father, who would later fold them into his group''s repertoire.

**The Birth of The New York Band**

In November 1988, at just 19 years old, Cherito joined The New York Band, the orchestra his father had founded in New York in 1986. He became the group''s lead voice, songwriter, arranger and co-producer, and the band stood out for modernizing merengue by fusing it with pop, house and R&B sounds, along with a cosmopolitan stage image that helped carry the genre beyond the Dominican Republic.

**Hits and Rise to Prominence**

Under his vocal leadership, The New York Band recorded some of the most remembered merengue songs of the era: "Si tú no estás" (recorded for Christmas 1987 and one of the group''s biggest hits), "Nadie como tú," "Dame vida," "Si tú eres mi hombre," "Dancing Mood," "Amada mía" and "Colé." With Cherito at the front, the group sold more than 2.5 million records across markets including Puerto Rico, the United States, Mexico, Colombia, Venezuela, Spain and the Dominican Republic, and performed on stages such as Madison Square Garden.

**Departure and Life as a Soloist and Producer**

In 1995, Cherito stepped away from the group to launch a solo and production career under the artistic name "Chery X," releasing the albums Cherito (1992), Que Tentación (Sony, 1995) — which produced the single "Qué tentación" — the compilation The Best of Cherito XXX: Love & Kisses (1996) and Tu Amor (BMG, 1997). The New York Band carried on without him until it formally disbanded in 1998.

In the years that followed, he focused mainly on songwriting, production and arranging, working with artists such as Celia Cruz, Wilfrido Vargas and Olga Tañón, collaborating with producer Sergio George, and serving as an exclusive composer for Warner Music Group.

**Comeback and the 2016 Reunion**

In 2007 he returned to the stage as a soloist with a merengue project with a more urban sound, which produced his biggest hit of that era, "Ella quiere un pedazo," along with singles such as "Vivir mi vida," "El protagonista," "Sé que te perdí" (with Pavel Núñez) and "Déjalo pa''l lunes."

In 2015 he took part in a tribute performance for The New York Band at the Soberano Awards, and in 2016, after receiving the Merit award, the original lineup formally reunited and launched the "Re:Encuentro World Tour," which was met with great enthusiasm from audiences. Reflecting on that moment, Cherito said: "He wasn''t wrong, and we''re reaping what we sowed," referring to his father''s vision in founding the band.

**Passing**

Cherito died suddenly on July 24, 2019, at age 50, after suffering a heart attack in his sleep at his home in Santo Domingo. He was survived by his wife, Aleyda, and his children Gabriel and Lía, as well as a son from a previous relationship.

**Discography**

As "Chery X" (solo period, 1990s): Cherito (1992), Que Tentación (Sony, 1995), The Best of Cherito XXX: Love & Kisses (compilation, 1996) and Tu Amor (BMG, 1997).

As "Cherito" (solo comeback, 2010s): "Ella quiere un pedazo" (2013, re-released 2015), "Vivir mi vida" (2013), "El protagonista" (2013), "Si tú eres mi hombre" (with Divas by Jiménez, 2014), "Sé que te perdí" (with Pavel Núñez, 2014) and "Déjalo pa''l lunes" (2016).

With The New York Band (selected hits, 1988–1995): "Si tú no estás," "Nadie como tú," "Dame vida," "Si tú eres mi hombre," "Dancing Mood," "Amada mía" and "Colé."

**Collaborations**

As a producer, arranger and composer he worked with Celia Cruz, Wilfrido Vargas, Olga Tañón and producer Sergio George, and collaborated on singles with Pavel Núñez and Divas by Jiménez.

**Legacy**

Cherito is remembered as the lead voice of The New York Band, one of the most influential merengue groups of the 1980s and 90s, and as the songwriter behind tracks that became generational classics of the genre. His work helped carry Dominican merengue to international stages and markets, and he continues to be remembered as one of the defining voices of merengue''s golden age.' WHERE slug = 'cherito';
