INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'primitivo-santos-y-su-orquesta' AND d.locale = 'es' AND d.document_type = 'artist_biography'), '1bb81986-f764-4aad-b3bb-16452ff66e97', 'artist', 'f625be23-cfa4-43fe-8bb5-0879b2fa492f');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Raquel Arias, born Raquel Arias Jiménez, is a Dominican singer, songwriter and accordionist in merengue típico, known as \"La Estrella del Merengue Típico.\" She belongs to the first wave of women to lead their own típico conjuntos rather than sing in front of someone else’s, and her \"¿Por qué te fuiste dulce amor?\" is one of the genre’s durable standards — a record that became a hit twice, eighteen years apart.","type":"text"}]},{"type":"paragraph","content":[{"text":"A family of accordionists","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Arias came up inside the music rather than toward it. Her father plays the accordion, and so did her grandfathers and uncles; the parties happened in her own house, and the instrument was simply present in the way furniture is. She began performing at around twelve, at family gatherings and private parties, and has now spent some three decades on the típico accordion — an unusual thing in a genre where women historically sang or played güira while men held the accordion.","type":"text"}]},{"type":"paragraph","content":[{"text":"The conjunto and the first records","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"She started recording in the 1990s and built a run of albums across the decade and beyond: La Fiera del Caribe, Sigue Encendía, La Insuperable in 2001, and Me voy con él in 2007. The nicknames accumulated with them — \"La Fiera\" and \"La Insuperable\" both come off album titles — though the one that stuck was \"La Estrella del Merengue Típico.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"Her signature record is \"No me olvides corazón,\" better known by its opening line as \"¿Por qué te fuiste dulce amor?,\" written by her brother ","type":"text"},{"type":"artistReference","attrs":{"artistId":"b1e4046f-97ff-4254-9a9d-789975f4a440","displayText":"Daniel Arias","occurrenceId":"3e724ca0-1711-4839-8c38-f9c02a0c8d17"}},{"text":" and cut in 1998. It did respectable business at the time and then did something unusual: it resurfaced in 2016, nearly two decades later, and became inescapable on Dominican radio and at neighborhood parties all over again.","type":"text"}]},{"type":"paragraph","content":[{"text":"The Christian years","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Arias then stepped away from secular music entirely, converting and devoting herself to the church. She kept performing, but in Christian merengue — including a rewritten, devotional version of her own biggest hit — and released the album Dios es todo para mí in 2016. She was explicit afterward about what the decision cost her: she turned down a million pesos for a single engagement and, by her account, international contracts worth some twenty million, saying she preferred to earn less and keep her peace. Few artists document the price of that kind of choice so plainly.","type":"text"}]},{"type":"paragraph","content":[{"text":"The return","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"She came back to secular merengue típico in 2019 with \"Aficia’ de ti,\" and marked it with a concert billed as \"El regreso en grande\" at Monte Bar in Santiago that August. The records have kept coming since — \"La grama chapiá,\" \"Amada y deseada\" in 2020, \"La Magdalena\" in 2026 — and she has stayed a working live act rather than a nostalgia booking.","type":"text"}]},{"type":"paragraph","content":[{"text":"Recognition","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Her awards have arrived mostly in the later stretch of her career:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Premios El Galardón, Grupo Tropical, in 2017,","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"a Premio Soberano for Conjunto Típico for the 2021 cycle, presented at the 2023 ceremony,","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"and Merenguera Típica del Año at the 2025 Glamour Music Awards.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Arias matters most as one of the women who changed who gets to hold the accordion. Alongside ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9333da06-ad03-44eb-9b81-c21d0ccdd0ea","displayText":"Fefita la Grande","occurrenceId":"c61f4a78-48ba-4cd7-9b16-9301aeff1c19"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"c462498c-0f4d-464f-b624-a576f8080e9d","displayText":"La India Canela","occurrenceId":"fa40072f-3faa-415f-91e7-825ea534920d"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"e9004428-e647-4a06-8316-b398452d46df","displayText":"María Díaz","occurrenceId":"4ad3e30e-d4aa-4e90-80d3-ed03f0dcfd0c"}},{"text":", she helped turn the female típico bandleader from an exception into an ordinary feature of the genre — there are now dozens of women fronting típico conjuntos in the Dominican Republic, which was not true when she started.","type":"text"}]},{"type":"paragraph","content":[{"text":"The second life of \"¿Por qué te fuiste dulce amor?\" is the other part of her legacy, and a reminder of how merengue típico actually works: the canon is set less by chart positions than by what keeps getting played at parties, and a song can wait twenty years for the country to decide it belongs to everyone.","type":"text"}]}]}'::jsonb, revision = revision - 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'raquel-arias' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Raquel Arias, born Raquel Arias Jiménez, is a Dominican singer, songwriter and accordionist in merengue típico, known as "La Estrella del Merengue Típico." She belongs to the first wave of women to lead their own típico conjuntos rather than sing in front of someone else’s, and her "¿Por qué te fuiste dulce amor?" is one of the genre’s durable standards — a record that became a hit twice, eighteen years apart.

**A family of accordionists**

Arias came up inside the music rather than toward it. Her father plays the accordion, and so did her grandfathers and uncles; the parties happened in her own house, and the instrument was simply present in the way furniture is. She began performing at around twelve, at family gatherings and private parties, and has now spent some three decades on the típico accordion — an unusual thing in a genre where women historically sang or played güira while men held the accordion.

**The conjunto and the first records**

She started recording in the 1990s and built a run of albums across the decade and beyond: La Fiera del Caribe, Sigue Encendía, La Insuperable in 2001, and Me voy con él in 2007. The nicknames accumulated with them — "La Fiera" and "La Insuperable" both come off album titles — though the one that stuck was "La Estrella del Merengue Típico."

Her signature record is "No me olvides corazón," better known by its opening line as "¿Por qué te fuiste dulce amor?," written by her brother Daniel Arias and cut in 1998. It did respectable business at the time and then did something unusual: it resurfaced in 2016, nearly two decades later, and became inescapable on Dominican radio and at neighborhood parties all over again.

**The Christian years**

Arias then stepped away from secular music entirely, converting and devoting herself to the church. She kept performing, but in Christian merengue — including a rewritten, devotional version of her own biggest hit — and released the album Dios es todo para mí in 2016. She was explicit afterward about what the decision cost her: she turned down a million pesos for a single engagement and, by her account, international contracts worth some twenty million, saying she preferred to earn less and keep her peace. Few artists document the price of that kind of choice so plainly.

**The return**

She came back to secular merengue típico in 2019 with "Aficia’ de ti," and marked it with a concert billed as "El regreso en grande" at Monte Bar in Santiago that August. The records have kept coming since — "La grama chapiá," "Amada y deseada" in 2020, "La Magdalena" in 2026 — and she has stayed a working live act rather than a nostalgia booking.

**Recognition**

Her awards have arrived mostly in the later stretch of her career:

- Premios El Galardón, Grupo Tropical, in 2017,  
- a Premio Soberano for Conjunto Típico for the 2021 cycle, presented at the 2023 ceremony,  
- and Merenguera Típica del Año at the 2025 Glamour Music Awards.

**Legacy**

Arias matters most as one of the women who changed who gets to hold the accordion. Alongside Fefita la Grande, La India Canela and María Díaz, she helped turn the female típico bandleader from an exception into an ordinary feature of the genre — there are now dozens of women fronting típico conjuntos in the Dominican Republic, which was not true when she started.

The second life of "¿Por qué te fuiste dulce amor?" is the other part of her legacy, and a reminder of how merengue típico actually works: the canon is set less by chart positions than by what keeps getting played at parties, and a song can wait twenty years for the country to decide it belongs to everyone.' WHERE slug = 'raquel-arias';
