INSERT INTO editorial_entity_references (editorial_document_id, occurrence_id, entity_type, target_artist_id) VALUES ((SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'tercer-cielo' AND d.locale = 'es' AND d.document_type = 'artist_biography'), '2801e463-37a0-435c-ac93-365c6f3a0e9a', 'artist', '629a7daa-5ab3-4b77-825f-6795b8c4a566');

UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The New York Band is one of the most influential groups in the history of modern merengue, and the one that best represented, from the mid-1980s onward, the sound and attitude of the Dominican diaspora in New York. With a proposal that combined merengue with disco, funk and danceable pop, along with choreography and costumes closer to international pop than to traditional merengue, the orchestra opened a new way of understanding the genre for the young audiences of the era.","type":"text"}]},{"type":"paragraph","content":[{"text":"Origins and Founding","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The group was born in 1986 in New York City, driven by Dominican entrepreneur and artistic promoter ","type":"text"},{"type":"artistReference","attrs":{"artistId":"42f4687d-840e-4092-8899-eb8b8d9f5986","displayText":"Chery Jiménez y su Tercera Brigada","occurrenceId":"82143cad-2ebb-4e8f-8d46-469b5517be4a"}},{"text":", with the support of musician","type":"text"},{"type":"artistReference","attrs":{"artistId":"2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"fc80626b-7f90-405f-b7ec-87f154f211a4"}},{"text":", whose name appeared alongside the orchestra''s on the cover of their first album. It emerged as part of a wave of merengue groups formed by Dominicans based in that city, alongside projects like ","type":"text"},{"type":"artistReference","attrs":{"artistId":"02b306b3-acc0-4800-b314-05683205d1c5","displayText":"Patrulla 15","occurrenceId":"082c2d68-4acd-4fe8-a2f6-11d1440cdf1b"}},{"text":", at a moment when the Dominican community in New York was seeking a band that reflected its own cultural identity.","type":"text"}]},{"type":"paragraph","content":[{"text":"First Lineup and Style","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In its early years, the group''s principal voice was singer Magda Lake. Shortly after, Irisneyda joined, originally from Santo Domingo, who had participated in a national talent competition before joining the orchestra. Musical direction and trombone were handled by Franklin Rivers, while Bolivita Quiñones provided the brass and woodwind sections and Anibalito Rijo handled keyboards and electric guitar. The group distinguished itself from the start through the quality of its instrumental execution and a choreographed stage presentation, with Alexandra as a notable dancer and backing vocalist.","type":"text"}]},{"type":"paragraph","content":[{"type":"artistReference","attrs":{"artistId":"35b79560-87dc-47aa-9f52-dda21faec41f","displayText":"Cherito","occurrenceId":"30650ad8-e6d1-4773-bf41-d90193b2f699"}},{"text":"''s Arrival and Consolidation","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 1988, ","type":"text"},{"type":"artistReference","attrs":{"artistId":"35b79560-87dc-47aa-9f52-dda21faec41f","displayText":"Cherito","occurrenceId":"7748a9da-6772-42da-ac84-f91557d055ca"}},{"text":" joined as a backing vocalist and soon became the lead voice. Along with Irisneyda, he became one of the main faces of the group, contributing his own compositions that quickly became part of the band''s repertoire. Under this lineup, The New York Band came to be considered the first merengue orchestra seriously aimed at the concert and theatrical spectacle format, not just the dance hall circuit, which set it apart from other groups of its time.","type":"text"}]},{"type":"paragraph","content":[{"text":"Hits and International Reach","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Their self-titled debut album, The New York Band (Karen Records, 1987), mixed merengue with disco, funk and pop rap, an unusual fusion for the genre at that moment. From there came songs like \"Colé,\" featuring Magda Lake on lead vocals. With ","type":"text"},{"type":"a